#!/usr/bin/env bash\n# Nightly Commit Emoji Annotator\n# Reads the last N git commit messages and prefixes each with an emoji\n# based on simple keyword matching.\n# If the environment variable GIT_LOG_MOCK is set, its value (newline-separated)\n# is used instead of calling git.\n\nset -euo pipefail\n\n# Number of commits to show (default 5)\nNUM=\"${1:-5}\"\n\n# Retrieve commit messages\nif [[ -n \"${GIT_LOG_MOCK:-}\" ]]; then\n  # Mock mode for tests\n  COMMIT_MESSAGES=$(printf \"%s\" \"$GIT_LOG_MOCK\")\nelse\n  COMMIT_MESSAGES=$(git log -n \"$NUM\" --pretty=format:%s)\nfi\n\n# Declare associative array of keyword -> emoji\ndeclare -A EMOJI_MAP=(\n  [\"fix\"]=\"🛠️\"\n  [\"bug\"]=\"🛠️\"\n  [\"add\"]=\"➕\"\n  [\"new\"]=\"➕\"\n  [\"remove\"]=\"➖\"\n  [\"delete\"]=\"➖\"\n  [\"refactor\"]=\"♻️\"\n  [\"docs\"]=\"📚\"\n  [\"doc\"]=\"📚\"\n  [\"test\"]=\"✅\"\n  [\"tests\"]=\"✅\"\n  [\"merge\"]=\"🔀\"\n  [\"performance\"]=\"🚀\"\n  [\"speed\"]=\"🚀\"\n  [\"security\"]=\"🔒\"\n  [\"ci\"]=\"🤖\"\n)\n\n# Function to find emoji for a message\nget_emoji() {\n  local msg_lower=$(echo \"$1\" | tr '[:upper:]' '[:lower:]')\n  for keyword in "${!EMOJI_MAP[@]}"; do\n    if [[ \"$msg_lower\" == *\"$keyword\"* ]]; then\n      echo "${EMOJI_MAP[$keyword]}"\n      return\n    fi\n  done\n  echo "💬"\n}\n\n# Process each line\nwhile IFS= read -r line; do\n  emoji=$(get_emoji \"$line\")\n  printf \"%s %s\n\" \"$emoji\" \"$line\"\n done <<< \"$COMMIT_MESSAGES\"\n
